var HOLLOW_LIMIT = 20;
/**
* 轮末交付检查（纯规则，不用 LLM）：
*  1. hollow：正文过短且无产物——疑似空洞回复；
*  2. empty_handoff：没产物、正文也没有实质结论词（空手交付）；
*  3. missing_citation：用过检索/网页却不标注 #rN 引用（事实无源）。
* 不合格不阻断交付（对话型不打断老板），由 Agent 注入提醒下轮自补。
*/
function closingCheck(ctx) {
	const problems = [];
	const stripped = ctx.content.replace(/[#>*_`~\-|]/g, "").replace(/\s+/g, "").trim();
	if (!ctx.hadArtifact && stripped.length < HOLLOW_LIMIT) problems.push("正文过短且本轮无产物，疑似空洞回复，请给出实质内容");
	if (ctx.hasWebEvidence && !/#r\d+/.test(ctx.content)) problems.push("本轮用过检索/网页材料但正文未标注 #rN 引用，请补上事实来源编号");
	return {
		ok: problems.length === 0,
		problems
	};
}
